const builderSources=['animals','barns','inventory','movements','weights','reproduction','litters','feeding','health','vaccines','alerts','trade','supplies','finance','cashflow','economics','overview','staff'];
export function listReportCatalog(role:Role){return{asOfDefault:currentFarmDate(),sources:sources.filter(source=>source.roles.includes(role)).map(source=>({...source,availableForBuilder:builderSources.includes(source.id),fields:source.fields.filter(item=>!item.roles||item.roles.includes(role)).map(item=>{const visible={...item};delete visible.roles;return visible;})})),granularities:['animal','event','day','month','barn','barn_day','barn_month','litter'],aggregates:[{id:'count',label:'Conteo'},{id:'sum',label:'Suma'},{id:'average',label:'Promedio'},{id:'percent',label:'Porcentaje con numerador/denominador'}],joins:[{id:'animal',label:'Animal',strategy:'filtrar hechos y combinar a una fila por animal'},{id:'barn',label:'Galpón',strategy:'agregar cada fuente por galpón antes de combinar'},{id:'lot',label:'Lote',strategy:'agregar cada fuente por galpón y lote antes de combinar'},{id:'operation',label:'Operación',strategy:'usar una relación de origen/reversión con identificador único'},{id:'period',label:'Periodo',strategy:'agregar cada fuente por periodo y dimensión antes de combinar'}]};}
export function validateReportParams(params:URLSearchParams,allowed:string[]){for(const key of params.keys())if(!allowed.includes(key))throw new ApiError(400,`Filtro o campo no admitido: ${key}`);}
function dateBounds(from:unknown,to:unknown){const start=from===undefined||from===null||from===''?null:String(from);const end=to===undefined||to===null||to===''?null:String(to);if(start&&!isValidDateString(start))throw new ApiError(400,'Fecha inicial inválida');if(end&&!isValidDateString(end))throw new ApiError(400,'Fecha final inválida');if(start&&end&&start>end)throw new ApiError(400,'El periodo inicial no puede superar la fecha final');return{start,end};}
async function scopeBarns(db:D1Database,scope:ReportScope){if(scope.allowedBarnNames===undefined||scope.allowedBarnNames===null)return null;if(!scope.allowedBarnNames.length)return[];const result=await db.prepare(`SELECT id FROM barns WHERE name IN (${scope.allowedBarnNames.map(()=>'?').join(',')})`).bind(...scope.allowedBarnNames).all<{id:number}>();return(result.results??[]).map(row=>Number(row.id));}
function addBarnFilter(barnId:unknown,allowed:number[]|null,column:string,where:string[],params:unknown[]){if(barnId===undefined||barnId===null||barnId==='')return;if(!/^\d+$/.test(String(barnId)))throw new ApiError(400,'Galpón inválido');const id=Number(barnId);if(allowed!==null&&!allowed.includes(id))throw new ApiError(403,'Sin acceso al galpón solicitado');where.push(`${column}=?`);params.push(id);}

export async function reportWeights(db:D1Database,filters:{from?:unknown;to?:unknown;barnId?:unknown;stageCode?:unknown;locationCode?:unknown;lotCode?:unknown;animalCode?:unknown},scope:ReportScope={}){
 const {start,end}=dateBounds(filters.from,filters.to);const barns=await scopeBarns(db,scope);const where=['1=1'];const params:unknown[]=[];addBarnFilter(filters.barnId,barns,'COALESCE(w.barn_id,a.barn_id)',where,params);if(barns!==null){if(!barns.length)where.push('0=1');else{where.push(`COALESCE(w.barn_id,a.barn_id) IN (${barns.map(()=>'?').join(',')})`);params.push(...barns);}}if(start){where.push('w.weighed_on>=?');params.push(start);}if(end){where.push('w.weighed_on<=?');params.push(end);}for(const [value,column] of [[filters.stageCode,'w.stage_code'],[filters.locationCode,'w.location_code'],[filters.lotCode,'w.lot_code'],[filters.animalCode,'a.code']] as const){if(value!==undefined&&value!==null&&value!==''){where.push(`${column}=?`);params.push(String(value));}}
 const total=await db.prepare(`SELECT COUNT(*) AS observations,AVG(w.weight_kg) AS average_kg,MIN(w.weight_kg) AS minimum_kg,MAX(w.weight_kg) AS maximum_kg FROM animal_weights w JOIN animals a ON a.id=w.animal_id WHERE ${where.join(' AND ')} AND NOT EXISTS(SELECT 1 FROM animal_weights correction WHERE correction.corrects_weight_id=w.id)`).bind(...params).first<Record<string,unknown>>();const rows=await db.prepare(`SELECT w.weighed_on AS date,w.stage_code AS stageCode,COUNT(*) AS observations,AVG(w.weight_kg) AS averageKg FROM animal_weights w JOIN animals a ON a.id=w.animal_id WHERE ${where.join(' AND ')} AND NOT EXISTS(SELECT 1 FROM animal_weights correction WHERE correction.corrects_weight_id=w.id) GROUP BY w.weighed_on,w.stage_code ORDER BY w.weighed_on,w.stage_code`).bind(...params).all<Record<string,unknown>>();return{filters:{from:start,to:end,barnId:filters.barnId??null,stageCode:filters.stageCode??null,locationCode:filters.locationCode??null,lotCode:filters.lotCode??null,animalCode:filters.animalCode??null},total:{observations:Number(total?.observations??0),averageKg:total?.average_kg===null?null:Number(total?.average_kg),minimumKg:total?.minimum_kg===null?null:Number(total?.minimum_kg),maximumKg:total?.maximum_kg===null?null:Number(total?.maximum_kg)},rows:(rows.results??[]).map(row=>({date:String(row.date),stageCode:row.stageCode===null?null:String(row.stageCode),observations:Number(row.observations),averageKg:Number(row.averageKg)})),chart:(rows.results??[]).map(row=>({date:String(row.date),stageCode:row.stageCode===null?null:String(row.stageCode),observations:Number(row.observations),averageKg:Number(row.averageKg)}))};
}

export async function reportBirths(db:D1Database,filters:{from?:unknown;to?:unknown;barnId?:unknown;locationCode?:unknown;lotCode?:unknown;motherCode?:unknown},scope:ReportScope={}){
 const {start,end}=dateBounds(filters.from,filters.to);const barns=await scopeBarns(db,scope);const where=['1=1'];const params:unknown[]=[];addBarnFilter(filters.barnId,barns,'l.barn_id',where,params);if(barns!==null){if(!barns.length)where.push('0=1');else{where.push(`l.barn_id IN (${barns.map(()=>'?').join(',')})`);params.push(...barns);}}if(start){where.push('l.farrowing_date>=?');params.push(start);}if(end){where.push('l.farrowing_date<=?');params.push(end);}for(const [value,column] of [[filters.locationCode,'l.location_code'],[filters.lotCode,'l.lot_code'],[filters.motherCode,'a.code']] as const){if(value!==undefined&&value!==null&&value!==''){where.push(`${column}=?`);params.push(String(value));}}
 const base=`SELECT l.id,l.farrowing_date,l.parity_number,a.code AS mother_code,l.barn_id,b.name AS barn_name,l.location_code,l.lot_code,l.live_count,l.stillborn_count,l.total_born,COALESCE(SUM(CASE WHEN e.event_type='death' THEN e.quantity ELSE 0 END),0) AS lactation_deaths FROM litters l JOIN animals a ON a.id=l.female_animal_id JOIN barns b ON b.id=l.barn_id LEFT JOIN litter_events e ON e.litter_id=l.id AND e.effective_date<=? WHERE ${where.join(' AND ')} GROUP BY l.id`;const raw=await db.prepare(base+' ORDER BY l.farrowing_date,l.id').bind(end??currentFarmDate(),...params).all<Record<string,unknown>>();const rows=(raw.results??[]).map(row=>{const totalBorn=Number(row.total_born);const deaths=Number(row.stillborn_count);const lactationDeaths=Number(row.lactation_deaths);return{id:String(row.id),farrowingDate:String(row.farrowing_date),parity:Number(row.parity_number),motherCode:String(row.mother_code),barnId:Number(row.barn_id),barnName:String(row.barn_name),locationCode:row.location_code===null?null:String(row.location_code),lotCode:row.lot_code===null?null:String(row.lot_code),liveBirths:Number(row.live_count),totalBorn,deaths,lactationDeaths,mortalityPct:totalBorn>0?100*deaths/totalBorn:null};});const totalBorn=rows.reduce((sum,row)=>sum+row.totalBorn,0);const deaths=rows.reduce((sum,row)=>sum+row.deaths,0);const rates=rows.flatMap(row=>row.mortalityPct===null?[]:[row.mortalityPct]);const averageMortalityPct=rates.length?rates.reduce((sum,value)=>sum+value,0)/rates.length:null;return{filters:{from:start,to:end,barnId:filters.barnId??null,locationCode:filters.locationCode??null,lotCode:filters.lotCode??null,motherCode:filters.motherCode??null},totals:{litters:rows.length,liveBirths:rows.reduce((sum,row)=>sum+row.liveBirths,0),totalBorn,deaths,lactationDeaths:rows.reduce((sum,row)=>sum+row.lactationDeaths,0),averageMortalityPct,globalMortalityPct:totalBorn>0?100*deaths/totalBorn:null},rows,chart:rows.map(row=>({farrowingDate:row.farrowingDate,barnName:row.barnName,motherCode:row.motherCode,liveBirths:row.liveBirths,deaths:row.deaths,lactationDeaths:row.lactationDeaths}))};
}

export type ReportDefinition={source:string;name:string;purpose:string;from?:string|null;to?:string|null;barnId?:number|string;columns:string[];groupBy?:string;orderBy?:string;orderDirection?:'asc'|'desc';filters?:Record<string,string>};
const reportFields:Record<string,string[]>={animals:['animalCode','animalType','sex','status','birthDate','ageDays','stage','barn','location','lot','currentWeightKg'],barns:['barn','capacity','status'],inventory:['asOf','barn','location','lot','stage','sex','heads'],movements:['effectiveDate','movementType','barn','heads','reason'],weights:['weighedOn','animalCode','stage','barn','location','lot','weightKg'],reproduction:['eventDate','animalCode','eventType','barn'],litters:['farrowingDate','motherCode','barn','location','lot','totalBorn','deaths','mortalityPct'],feeding:['effectiveDate','barn','stage','feed','quantityKg','currency','cost'],health:['effectiveDate','animalCode','eventType','product','barn'],vaccines:['scheduledDate','animalCode','vaccine','status','barn','location','lot'],alerts:['dueDate','type','status','priority','barn'],trade:['operationDate','direction','animalCode','barn','currency','amount'],supplies:['effectiveDate','supply','movementType','barn','quantity'],finance:['operationDate','direction','category','barn','currency','amount'],cashflow:['settlementDate','direction','category','barn','currency','amount'],overview:['rowType','month','barn','currency','sales','feedCost','vaccineCount','reproductionCount'],economics:['month','barn','currency','sales','feedCost'],staff:['name','username','role','barn','active']};
function checkDefinition(input:unknown,role:Role){
 if(!input||typeof input!=='object'||Array.isArray(input))throw new ApiError(400,'Definición de reporte inválida');const d=input as Record<string,unknown>;
 if(typeof d.source!=='string'||!builderSources.includes(d.source))throw new ApiError(400,'Fuente no disponible para el generador');
 const sourceMeta=sources.find(item=>item.id===d.source);if(!sourceMeta?.roles.includes(role))throw new ApiError(403,'Este perfil no puede consultar esta fuente');const visibleFields=sourceMeta.fields.filter(item=>!item.roles||item.roles.includes(role)).map(item=>item.key);const allowed=(reportFields[d.source]??[]).filter(key=>visibleFields.includes(key));const cols=Array.isArray(d.columns)?d.columns:[];if(!cols.length||cols.length>12||cols.some(c=>typeof c!=='string'||!allowed.includes(c)))throw new ApiError(400,'Seleccione columnas permitidas');
 if(['finance','cashflow'].includes(d.source as string)&&!['administrador','responsable'].includes(role))throw new ApiError(403,'Este perfil no puede consultar importes financieros');
 const {start,end}=dateBounds(d.from,d.to);const filters=(d.filters&&typeof d.filters==='object'&&!Array.isArray(d.filters)?d.filters:{}) as Record<string,unknown>;if(d.barnId!==undefined&&typeof d.barnId!=='string'&&typeof d.barnId!=='number')throw new ApiError(400,'Galpón inválido');const filterColumns:Record<string,string[]>={animals:['barnId','lot','stage','status','animalCode'],barns:['barnId'],inventory:['barnId','lot','stage'],movements:['barnId','lot','movementType'],weights:['barnId','lot','stage','animalCode'],reproduction:['barnId','animalCode','eventType'],litters:['barnId','lot','motherCode'],feeding:['barnId','feed'],health:['barnId','animalCode','eventType','product'],vaccines:['barnId','lot','status','animalCode'],alerts:['barnId','type','status'],trade:['barnId','direction','animalCode'],supplies:['barnId','supply','movementType'],finance:['barnId','direction','category','currency'],cashflow:['barnId','direction','category','currency'],overview:['barnId','currency'],economics:['barnId','currency'],staff:['barnId','role','username']};const allowedFilters=filterColumns[d.source]??[];for(const key of Object.keys(filters))if(!allowedFilters.includes(key))throw new ApiError(400,`Filtro no admitido: ${key}`);
 const groupBy=typeof d.groupBy==='string'&&d.groupBy?d.groupBy:undefined;if(groupBy&&groupBy.split(',').some(key=>!allowed.includes(key)&&(['finance','cashflow'].includes(d.source as string)&&key==='month'?false:true)))throw new ApiError(400,'Agrupación no permitida');const orderBy=typeof d.orderBy==='string'&&d.orderBy?d.orderBy:undefined;if(orderBy&&!allowed.includes(orderBy))throw new ApiError(400,'Orden no permitido');
 return{source:d.source,name:typeof d.name==='string'?d.name.trim():'',purpose:typeof d.purpose==='string'?d.purpose.trim():'',from:start,to:end,barnId:d.barnId,columns:cols as string[],groupBy,orderBy,orderDirection:d.orderDirection==='desc'?'desc' as const:'asc' as const,filters:Object.fromEntries(Object.entries(filters).map(([k,v])=>[k,String(v)]))};
}
function scopedClause(barnIds:number[]|null,column:string,where:string[],params:unknown[]){if(barnIds===null)return;if(!barnIds.length){where.push('0=1');return;}where.push(`${column} IN (${barnIds.map(()=>'?').join(',')})`);params.push(...barnIds);}
async function reportEconomics(db:D1Database,d:ReportDefinition,scope:ReportScope,limit:number,rejectOverflow:boolean){
 const barns=await scopeBarns(db,scope);const filters=d.filters??{};const salesWhere:string[]=["f.source_type='animal_sale'","f.reversed_at IS NULL"];const feedWhere:string[]=["fm.movement_type='delivery'"];const salesArgs:unknown[]=[];const feedArgs:unknown[]=[];
 if(d.from){salesWhere.push('f.operation_date>=?');salesArgs.push(d.from);feedWhere.push('fm.effective_date>=?');feedArgs.push(d.from);}if(d.to){salesWhere.push('f.operation_date<=?');salesArgs.push(d.to);feedWhere.push('fm.effective_date<=?');feedArgs.push(d.to);}
 const selectedBarn=d.barnId??filters.barnId;if(selectedBarn!==undefined&&selectedBarn!==null&&selectedBarn!==''){addBarnFilter(selectedBarn,barns,'fa.barn_id',salesWhere,salesArgs);addBarnFilter(selectedBarn,barns,'fm.destination_barn_id',feedWhere,feedArgs);}else{scopedClause(barns,'fa.barn_id',salesWhere,salesArgs);scopedClause(barns,'fm.destination_barn_id',feedWhere,feedArgs);}
 const currency=filters.currency;if(currency){salesWhere.push('f.currency_code=?');salesArgs.push(currency);feedWhere.push('fm.currency_code=?');feedArgs.push(currency);}
 const sortExpression:Record<string,string>={month:'d.month',barn:'b.name',currency:'d.currency',sales:'COALESCE(s.sales,0)',feedCost:'COALESCE(f.feedCost,0)'};const order=d.orderBy?`${sortExpression[d.orderBy]} ${d.orderDirection}`:'d.month,b.name,d.currency';const sql=`WITH sales AS (SELECT substr(f.operation_date,1,7) month,fa.barn_id,f.currency_code currency,SUM(fa.amount_minor)/100.0 sales FROM financial_entries f JOIN financial_allocations fa ON fa.entry_id=f.id WHERE ${salesWhere.join(' AND ')} GROUP BY substr(f.operation_date,1,7),fa.barn_id,f.currency_code), feed AS (SELECT substr(fm.effective_date,1,7) month,fm.destination_barn_id barn_id,fm.currency_code currency,SUM(fm.total_cost_minor)/100.0 feedCost FROM feed_movements fm WHERE ${feedWhere.join(' AND ')} GROUP BY substr(fm.effective_date,1,7),fm.destination_barn_id,fm.currency_code), dimensions AS (SELECT month,barn_id,currency FROM sales UNION SELECT month,barn_id,currency FROM feed) SELECT d.month,b.name barn,d.currency,COALESCE(s.sales,0) sales,COALESCE(f.feedCost,0) feedCost FROM dimensions d JOIN barns b ON b.id=d.barn_id LEFT JOIN sales s ON s.month=d.month AND s.barn_id=d.barn_id AND s.currency=d.currency LEFT JOIN feed f ON f.month=d.month AND f.barn_id=d.barn_id AND f.currency=d.currency ORDER BY ${order} LIMIT ?`;
 const result=await db.prepare(sql).bind(...salesArgs,...feedArgs,limit+1).all<Record<string,unknown>>();const overflow=(result.results??[]).length>limit;if(overflow&&rejectOverflow)throw new ApiError(413,`El informe supera el límite de ${limit} filas. Agregue filtros o reduzca el periodo y vuelva a exportar.`);const sourceRows=(result.results??[]).slice(0,limit);const rows=sourceRows.map(row=>Object.fromEntries(d.columns.map(column=>[column,row[column]??null])));const groups:Record<string,{count:number;sum:number;average:number|null;income:number;expense:number;balance:number}>={};for(const row of sourceRows){const key=d.groupBy?[...(d.groupBy.split(',').includes('currency')?[]:[String(row.currency??'Sin moneda')]),...d.groupBy.split(',').map(field=>String(row[field]??'Sin dato'))].join(' · '):undefined;if(key){const group=groups[key]??{count:0,sum:0,average:null,income:0,expense:0,balance:0};const income=Number(row.sales)||0;const expense=Number(row.feedCost)||0;group.count++;group.income+=income;group.expense+=expense;group.balance+=income-expense;group.sum+=income+expense;group.average=group.sum/group.count;groups[key]=group;}}
 const moneyTotals:Record<string,{income:number;expense:number;balance:number}>={};for(const row of sourceRows){const currency=String(row.currency);const item=moneyTotals[currency]??{income:0,expense:0,balance:0};item.income+=Number(row.sales)||0;item.expense+=Number(row.feedCost)||0;item.balance=item.income-item.expense;moneyTotals[currency]=item;}
 return{definition:d,asOf:currentFarmDate(),rowCount:rows.length,rows,groups,moneyTotals,totals:{rows:rows.length,sum:null,average:null,amount:null,income:null,expense:null,balance:null,weightKg:null},truncated:overflow};
}
async function reportOverview(db:D1Database,d:ReportDefinition,scope:ReportScope,limit:number,rejectOverflow:boolean){
 const economics=await reportEconomics(db,{...d,source:'economics',columns:['month','barn','currency','sales','feedCost'],orderBy:undefined,groupBy:undefined},scope,limit+1,false);const barns=await scopeBarns(db,scope);const vaccineWhere=["v.status='pending'"];const reproductionWhere=['1=1'];const vaccineArgs:unknown[]=[];const reproductionArgs:unknown[]=[];
 for(const [date,operator] of [[d.from,'>='],[d.to,'<=']] as const)if(date){vaccineWhere.push(`v.scheduled_date${operator}?`);vaccineArgs.push(date);reproductionWhere.push(`re.event_date${operator}?`);reproductionArgs.push(date);}
 const selectedBarn=d.barnId??d.filters?.barnId;if(selectedBarn!==undefined&&selectedBarn!==null&&selectedBarn!==''){addBarnFilter(selectedBarn,barns,'a.barn_id',vaccineWhere,vaccineArgs);addBarnFilter(selectedBarn,barns,'c.barn_id',reproductionWhere,reproductionArgs);}else{scopedClause(barns,'a.barn_id',vaccineWhere,vaccineArgs);scopedClause(barns,'c.barn_id',reproductionWhere,reproductionArgs);}
 const activity=await db.prepare(`WITH vaccines AS (SELECT substr(v.scheduled_date,1,7) month,a.barn_id,COUNT(*) n FROM vaccine_occurrences v JOIN animals a ON a.id=v.animal_id WHERE ${vaccineWhere.join(' AND ')} GROUP BY substr(v.scheduled_date,1,7),a.barn_id), reproduction AS (SELECT substr(re.event_date,1,7) month,c.barn_id,COUNT(*) n FROM reproduction_events re JOIN reproduction_cycles c ON c.id=re.cycle_id WHERE ${reproductionWhere.join(' AND ')} GROUP BY substr(re.event_date,1,7),c.barn_id), dimensions AS (SELECT month,barn_id FROM vaccines UNION SELECT month,barn_id FROM reproduction) SELECT d.month,b.name barn,COALESCE(v.n,0) vaccineCount,COALESCE(r.n,0) reproductionCount FROM dimensions d JOIN barns b ON b.id=d.barn_id LEFT JOIN vaccines v ON v.month=d.month AND v.barn_id=d.barn_id LEFT JOIN reproduction r ON r.month=d.month AND r.barn_id=d.barn_id ORDER BY d.month,b.name LIMIT ?`).bind(...vaccineArgs,...reproductionArgs,limit+1).all<Record<string,unknown>>();
 const sourceRows:Record<string,unknown>[]=[...economics.rows.map(row=>({...row,rowType:'Importes',vaccineCount:null,reproductionCount:null})),...(activity.results??[]).map(row=>({...row,rowType:'Actividad',currency:'No aplica',sales:null,feedCost:null}))];const order=d.orderBy??'month';sourceRows.sort((a,b)=>{const left=a[order];const right=b[order];const compared=typeof left==='number'&&typeof right==='number'?left-right:String(left??'').localeCompare(String(right??''));return (d.orderDirection==='desc'?-compared:compared)||String(a.barn).localeCompare(String(b.barn))||String(a.rowType).localeCompare(String(b.rowType));});const overflow=economics.truncated||(activity.results??[]).length>limit||sourceRows.length>limit;if(overflow&&rejectOverflow)throw new ApiError(413,`El informe supera el límite de ${limit} filas. Agregue filtros o reduzca el periodo y vuelva a exportar.`);const visible=sourceRows.slice(0,limit);const moneyTotals:Record<string,{income:number;expense:number;balance:number}>={};for(const row of visible)if(row.rowType==='Importes'){const currency=String(row.currency);const value=moneyTotals[currency]??{income:0,expense:0,balance:0};value.income+=Number(row.sales)||0;value.expense+=Number(row.feedCost)||0;value.balance=value.income-value.expense;moneyTotals[currency]=value;}
 const groups:Record<string,{count:number;sum:number;average:number|null;income:number;expense:number;balance:number}>={};for(const row of visible)if(d.groupBy){const keys=d.groupBy.split(',');const key=[...(keys.includes('currency')?[]:[String(row.currency)]),...keys.map(field=>String(row[field]??'Sin dato'))].join(' · ');const group=groups[key]??{count:0,sum:0,average:null,income:0,expense:0,balance:0};group.count++;group.income+=Number(row.sales)||0;group.expense+=Number(row.feedCost)||0;group.balance=group.income-group.expense;group.sum=group.income+group.expense;groups[key]=group;}
 return{definition:d,asOf:currentFarmDate(),rowCount:visible.length,rows:visible.map(row=>Object.fromEntries(d.columns.map(column=>[column,row[column]??null]))),groups,moneyTotals,totals:{rows:visible.length,sum:null,average:null,amount:null,income:null,expense:null,balance:null,weightKg:null,vaccineCount:visible.reduce((n,row)=>n+(Number(row.vaccineCount)||0),0),reproductionCount:visible.reduce((n,row)=>n+(Number(row.reproductionCount)||0),0)},truncated:overflow};
}
export async function previewCustomReport(db:D1Database,input:unknown,role:Role,scope:ReportScope,options:{limit?:number;rejectOverflow?:boolean}={}){
 const d=checkDefinition(input,role);if(d.source==='overview')return reportOverview(db,d,scope,options.limit??500,options.rejectOverflow??false);if(d.source==='economics')return reportEconomics(db,d,scope,options.limit??500,options.rejectOverflow??false);const barns=await scopeBarns(db,scope);const where:string[]=['1=1'];const args:unknown[]=[];
 const dateColumns:Record<string,string>={animals:'a.entry_date',barns:'b.created_at',inventory:'im.effective_date',movements:'im.effective_date',weights:'w.weighed_on',reproduction:'re.event_date',litters:'l.farrowing_date',feeding:'fm.effective_date',health:'h.effective_date',vaccines:'v.scheduled_date',alerts:'al.due_date',trade:'f.operation_date',supplies:'fm.effective_date',finance:'f.operation_date',cashflow:'fs.settlement_date',staff:'ub.assigned_at'};const dateColumn=dateColumns[d.source];if(d.from&&dateColumn){where.push(`${dateColumn}>=?`);args.push(d.from);}if(d.to&&dateColumn){where.push(`${dateColumn}<=?`);args.push(d.to);}
 const barnColumns:Record<string,string>={animals:'a.barn_id',barns:'b.id',inventory:'im.barn_id',movements:'im.barn_id',weights:'COALESCE(w.barn_id,a.barn_id)',reproduction:'c.barn_id',litters:'l.barn_id',feeding:'fm.destination_barn_id',health:'hea.barn_id',vaccines:'a.barn_id',alerts:'al.barn_id',trade:'fa.barn_id',supplies:'fm.destination_barn_id',finance:'fa.barn_id',cashflow:'fa.barn_id',staff:'ub.barn_id'};const barnColumn=barnColumns[d.source];const selectedBarn=d.barnId??d.filters.barnId;if(barnColumn){if(selectedBarn!==undefined&&selectedBarn!==null&&selectedBarn!=='')addBarnFilter(selectedBarn,barns,barnColumn,where,args);else scopedClause(barns,barnColumn,where,args);}const filterExpressions:Record<string,Record<string,string>>={animals:{lot:'a.lot_code',stage:'a.current_stage_code',status:'a.status',animalCode:'a.code'},inventory:{lot:'im.lot_code',stage:'im.stage_code'},movements:{lot:'im.lot_code',movementType:'im.movement_type'},weights:{lot:'w.lot_code',stage:'w.stage_code',animalCode:'a.code'},reproduction:{animalCode:'a.code',eventType:'re.event_type'},litters:{lot:'l.lot_code',motherCode:'a.code'},feeding:{feed:'fm.feed_code'},health:{animalCode:'hea.animal_code_snapshot',eventType:'h.event_type',product:'h.product'},vaccines:{lot:'a.lot_code',status:'v.status',animalCode:'a.code'},alerts:{type:'al.alert_type',status:'al.status'},trade:{direction:'f.direction',animalCode:'COALESCE(a.code,f.source_id)'},supplies:{supply:'fm.feed_code',movementType:'fm.movement_type'},finance:{direction:'f.direction',category:'f.category',currency:'f.currency_code'},cashflow:{direction:'f.direction',category:'f.category',currency:'f.currency_code'},staff:{role:'u.role',username:'u.username'}};for(const[key,value]of Object.entries(d.filters)){const expression=filterExpressions[d.source]?.[key];if(expression&&value){where.push(`${expression}=?`);args.push(value);}}
 let sql='';
 if(d.source==='animals')sql=`SELECT a.code animalCode,a.animal_type animalType,a.sex,a.status,a.birth_date birthDate,CASE WHEN a.birth_date IS NULL THEN NULL ELSE CAST(julianday(?) - julianday(a.birth_date) AS INTEGER) END ageDays,a.current_stage_code stage,b.name barn,a.location_code location,a.lot_code lot, (SELECT w.weight_kg FROM animal_weights w WHERE w.animal_id=a.id AND NOT EXISTS(SELECT 1 FROM animal_weights c WHERE c.corrects_weight_id=w.id) ORDER BY w.weighed_on DESC,w.id DESC LIMIT 1) currentWeightKg FROM animals a JOIN barns b ON b.id=a.barn_id WHERE ${where.join(' AND ')} AND a.is_active=1`;
 if(d.source==='barns')sql=`SELECT b.name barn,b.capacity,b.status FROM barns b WHERE ${where.join(' AND ')}`;
 if(d.source==='inventory')sql=`SELECT MAX(im.effective_date) asOf,b.name barn,im.location_code location,im.lot_code lot,im.stage_code stage,im.sex,SUM(CASE WHEN im.movement_type IN ('initial','purchase','birth','transfer_in') THEN im.quantity WHEN im.movement_type IN ('sale','death','transfer_out') THEN -im.quantity ELSE im.quantity END) heads FROM inventory_movements im JOIN barns b ON b.id=im.barn_id WHERE ${where.join(' AND ')} GROUP BY im.barn_id,im.location_code,im.lot_code,im.stage_code,im.sex`;
 if(d.source==='movements')sql=`SELECT im.effective_date effectiveDate,im.movement_type movementType,b.name barn,CASE WHEN im.movement_type IN ('sale','death','transfer_out') THEN -im.quantity ELSE im.quantity END heads,COALESCE(im.cause_code,im.notes,'') reason,im.lot_code lot FROM inventory_movements im JOIN barns b ON b.id=im.barn_id WHERE ${where.join(' AND ')}`;
 if(d.source==='weights')sql=`SELECT w.weighed_on weighedOn,a.code animalCode,w.stage_code stage,b.name barn,w.location_code location,w.lot_code lot,w.weight_kg weightKg FROM animal_weights w JOIN animals a ON a.id=w.animal_id LEFT JOIN barns b ON b.id=COALESCE(w.barn_id,a.barn_id) WHERE ${where.join(' AND ')} AND NOT EXISTS(SELECT 1 FROM animal_weights c WHERE c.corrects_weight_id=w.id)`;
 if(d.source==='litters')sql=`SELECT l.farrowing_date farrowingDate,a.code motherCode,b.name barn,l.location_code location,l.lot_code lot,l.total_born totalBorn,l.stillborn_count+COALESCE((SELECT SUM(e.quantity) FROM litter_events e WHERE e.litter_id=l.id AND e.event_type='death' AND e.effective_date<=?),0) deaths,CASE WHEN l.total_born>0 THEN 100.0*(l.stillborn_count+COALESCE((SELECT SUM(e.quantity) FROM litter_events e WHERE e.litter_id=l.id AND e.event_type='death' AND e.effective_date<=?),0))/l.total_born END mortalityPct FROM litters l JOIN animals a ON a.id=l.female_animal_id JOIN barns b ON b.id=l.barn_id WHERE ${where.join(' AND ')}`;
 if(d.source==='reproduction')sql=`SELECT re.event_date eventDate,a.code animalCode,re.event_type eventType,b.name barn FROM reproduction_events re JOIN reproduction_cycles c ON c.id=re.cycle_id JOIN animals a ON a.id=c.female_animal_id JOIN barns b ON b.id=c.barn_id WHERE ${where.join(' AND ')}`;
 if(d.source==='feeding')sql=`SELECT fm.effective_date effectiveDate,b.name barn,a.current_stage_code stage,fm.feed_code feed,fm.quantity_kg quantityKg,fm.currency_code currency,fm.total_cost_minor/100.0 cost FROM feed_movements fm LEFT JOIN barns b ON b.id=fm.destination_barn_id LEFT JOIN animals a ON a.id=fm.animal_id WHERE ${where.join(' AND ')}`;
 if(d.source==='health')sql=`SELECT h.effective_date effectiveDate,hea.animal_code_snapshot animalCode,h.event_type eventType,h.product,b.name barn FROM health_events h JOIN health_event_animals hea ON hea.health_event_id=h.id JOIN barns b ON b.id=hea.barn_id WHERE EXISTS(SELECT 1 FROM operation_log o WHERE o.id=h.operation_log_id AND o.status='committed') AND ${where.join(' AND ')}`;
 if(d.source==='finance')sql=`SELECT f.operation_date operationDate,f.direction,f.category,COALESCE(fa.barn_name_snapshot,b.name,'General de granja') barn,f.currency_code currency,fa.amount_minor/100.0 amount FROM financial_entries f JOIN financial_allocations fa ON fa.entry_id=f.id LEFT JOIN barns b ON b.id=fa.barn_id WHERE ${where.join(' AND ')}`;
 if(d.source==='cashflow')sql=`SELECT fs.settlement_date settlementDate,f.direction,f.category,COALESCE(fa.barn_name_snapshot,b.name,'General de granja') barn,f.currency_code currency,fsa.amount_minor/100.0 amount FROM financial_settlements fs JOIN financial_settlement_allocations fsa ON fsa.settlement_id=fs.id JOIN financial_allocations fa ON fa.id=fsa.financial_allocation_id JOIN financial_entries f ON f.id=fs.financial_entry_id LEFT JOIN barns b ON b.id=fa.barn_id WHERE ${where.join(' AND ')}`;
 if(d.source==='vaccines')sql=`SELECT v.scheduled_date scheduledDate,v.animal_code_snapshot animalCode,v.vaccine_name_snapshot vaccine,v.status,b.name barn,a.location_code location,a.lot_code lot FROM vaccine_occurrences v JOIN animals a ON a.id=v.animal_id LEFT JOIN barns b ON b.id=a.barn_id WHERE ${where.join(' AND ')} AND v.status='pending'`;
 if(d.source==='alerts')sql=`SELECT al.due_date dueDate,al.alert_type type,al.status,COALESCE(json_extract(al.detail_json,'$.priority'),'normal') priority,COALESCE(al.barn_name_snapshot,b.name,'') barn FROM alert_occurrences al LEFT JOIN barns b ON b.id=al.barn_id WHERE ${where.join(' AND ')}`;
 if(d.source==='trade')sql=`SELECT f.operation_date operationDate,f.direction,COALESCE(a.code,f.source_id) animalCode,COALESCE(fa.barn_name_snapshot,b.name,'General') barn,f.currency_code currency,fa.amount_minor/100.0 amount FROM financial_entries f JOIN financial_allocations fa ON fa.entry_id=f.id LEFT JOIN barns b ON b.id=fa.barn_id LEFT JOIN animals a ON CAST(a.id AS TEXT)=f.source_id WHERE ${where.join(' AND ')} AND f.source_type IN ('animal_sale','animal_purchase') AND f.reversed_at IS NULL`;
 if(d.source==='supplies')sql=`SELECT fm.effective_date effectiveDate,fm.feed_code supply,fm.movement_type movementType,COALESCE(b.name,'Almacén general') barn,fm.quantity_kg quantity FROM feed_movements fm LEFT JOIN barns b ON b.id=fm.destination_barn_id WHERE ${where.join(' AND ')}`;
 if(d.source==='staff')sql=`SELECT u.name,u.username,u.role,b.name barn,CASE WHEN u.is_active=1 THEN 'activa' ELSE 'inactiva' END active FROM user_barns ub JOIN users u ON u.id=ub.user_id JOIN barns b ON b.id=ub.barn_id WHERE ${where.join(' AND ')}`;
 if(d.source==='animals')args.unshift(currentFarmDate());if(d.source==='litters')args.unshift(d.to??currentFarmDate(),d.to??currentFarmDate());const limit=options.limit??500;const result=await db.prepare(sql+' ORDER BY '+(d.orderBy?`"${d.orderBy}" ${d.orderDirection}`:'1')+' LIMIT ?').bind(...args,limit+1).all<Record<string,unknown>>();const overflow=(result.results??[]).length>limit;if(overflow&&options.rejectOverflow)throw new ApiError(413,`El informe supera el límite de ${limit} filas. Agregue filtros o reduzca el periodo y vuelva a exportar.`);const canReadMoney=role==='administrador'||role==='responsable';const sourceRows=(result.results??[]).slice(0,limit).map(row=>canReadMoney?row:Object.fromEntries(Object.entries(row).filter(([key])=>key!=='amount'&&key!=='cost')));const rows=sourceRows.map(row=>Object.fromEntries(d.columns.map(column=>[column,row[column]??null])));
 const groups:Record<string,{count:number;sum:number;average:number|null;income:number;expense:number;balance:number}>={};if(d.groupBy){const keys=d.groupBy.split(',');for(const row of sourceRows){const dimensions=keys.map(group=>group==='month'?String(row.operationDate??row.settlementDate??'').slice(0,7):String(row[group]??'Sin dato'));if(['finance','cashflow','trade'].includes(d.source as string)&&!keys.includes('currency'))dimensions.unshift(String(row.currency??'Sin moneda'));const key=dimensions.join(' · ');const entry=groups[key]??{count:0,sum:0,average:null,income:0,expense:0,balance:0};entry.count++;const numeric=Number(row.amount??row.weightKg??row.totalBorn??row.mortalityPct??row.quantityKg??row.heads);if(Number.isFinite(numeric)){entry.sum+=numeric;if(row.direction==='income')entry.income+=numeric;if(row.direction==='expense')entry.expense+=numeric;entry.balance=entry.income-entry.expense;}entry.average=entry.sum/entry.count;groups[key]=entry;}}
 const currencies=[...new Set(sourceRows.map(row=>String(row.currency??'')).filter(Boolean))];const moneyTotals=canReadMoney?Object.fromEntries(currencies.map(currency=>{const subset=sourceRows.filter(row=>row.currency===currency);const income=subset.reduce((sum,row)=>sum+(row.direction==='income'?Number(row.amount)||0:0),0);const expense=subset.reduce((sum,row)=>sum+(row.direction==='expense'?Number(row.amount)||0:0),0);return[currency,{income,expense,balance:income-expense}];})):{};const metricField:Record<string,string>={barns:'capacity',inventory:'heads',movements:'heads',weights:'weightKg',litters:'totalBorn',feeding:'quantityKg',supplies:'quantity'};const metricValues=metricField[d.source]?sourceRows.map(row=>Number(row[metricField[d.source]])).filter(Number.isFinite):[];return{definition:d,asOf:currentFarmDate(),rowCount:rows.length,rows,groups,moneyTotals,totals:{rows:rows.length,sum:metricValues.reduce((sum,value)=>sum+value,0),average:metricValues.length?metricValues.reduce((sum,value)=>sum+value,0)/metricValues.length:null,amount:(!canReadMoney||['finance','cashflow','trade'].includes(d.source))?null:sourceRows.reduce((sum,r)=>sum+(Number(r.amount)||0),0),income:(!canReadMoney||['finance','cashflow','trade'].includes(d.source))?null:sourceRows.reduce((sum,r)=>sum+(r.direction==='income'?Number(r.amount)||0:0),0),expense:(!canReadMoney||['finance','cashflow','trade'].includes(d.source))?null:sourceRows.reduce((sum,r)=>sum+(r.direction==='expense'?Number(r.amount)||0:0),0),balance:(!canReadMoney||['finance','cashflow','trade'].includes(d.source))?null:sourceRows.reduce((sum,r)=>sum+(r.direction==='income'?Number(r.amount)||0:r.direction==='expense'?-(Number(r.amount)||0):0),0),weightKg:sourceRows.length&&d.source==='weights'?sourceRows.reduce((sum,r)=>sum+(Number(r.weightKg)||0),0)/sourceRows.length:null},truncated:overflow};
}

export const MAX_REPORT_EXPORT_ROWS=10_000;
export async function exportCustomReport(db:D1Database,input:unknown,role:Role,scope:ReportScope){
 return previewCustomReport(db,input,role,scope,{limit:MAX_REPORT_EXPORT_ROWS,rejectOverflow:true});
}
export async function listReportDefinitions(db:D1Database,userId:number){const rows=await db.prepare('SELECT id,name,purpose,definition_json,created_at,updated_at FROM report_definitions WHERE owner_user_id=? ORDER BY updated_at DESC').bind(userId).all<Record<string,unknown>>();return(rows.results??[]).map(row=>({...row,definition:JSON.parse(String(row.definition_json))}));}
type ReportDefinitionWriteOptions={id?:string;operationKey?:string;action?:'create'|'update'|'duplicate';operationPayload?:unknown};
type ReportDefinitionWriteResult={id:string;name:string;purpose:string;replayed?:boolean};
async function writeReportDefinition(db:D1Database,userId:number,d:ReportDefinition,options:ReportDefinitionWriteOptions):Promise<ReportDefinitionWriteResult>{
 const action=options.action??(options.id?'update':'create');
 const payload=options.operationPayload??{action,id:options.id??null,definition:d};
 const replay=await lookupExistingOperation(db,userId,options.operationKey,payload);
 if(replay)return{...(replay.result as Omit<ReportDefinitionWriteResult,'replayed'>),replayed:true};
 if(options.id){const existing=await db.prepare('SELECT id FROM report_definitions WHERE id=? AND owner_user_id=?').bind(options.id,userId).first();if(!existing)throw new ApiError(404,'Informe no encontrado');}
 const id=options.id??crypto.randomUUID();const now=new Date().toISOString();
 const result={id,name:d.name,purpose:d.purpose};
 const claim=await createOperationClaim({operationKey:options.operationKey,operationType:`reports.definition.${action}`,authorUserId:userId,entityType:'report_definition',entityId:null,effectiveDate:currentFarmDate(),payload,result});
 const effect=options.id
  ?db.prepare('UPDATE report_definitions SET name=?,purpose=?,definition_json=?,updated_at=? WHERE id=? AND owner_user_id=?').bind(d.name,d.purpose,JSON.stringify(d),now,options.id,userId)
  :db.prepare('INSERT INTO report_definitions(id,owner_user_id,name,purpose,definition_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?)').bind(id,userId,d.name,d.purpose,JSON.stringify(d),now,now);
 const committed=await commitOperation(db,claim,[effect],[]);
 return{...(committed.result as Omit<ReportDefinitionWriteResult,'replayed'>),replayed:committed.replayed};
}
export async function saveReportDefinition(db:D1Database,userId:number,role:Role,input:unknown,options:ReportDefinitionWriteOptions={}){const d=checkDefinition(input,role);if(d.name.length<1||d.name.length>120||d.purpose.length<1||d.purpose.length>500)throw new ApiError(400,'El informe requiere nombre y finalidad');return writeReportDefinition(db,userId,d,options);}
export async function getReportDefinition(db:D1Database,userId:number,id:string){const row=await db.prepare('SELECT id,name,purpose,definition_json FROM report_definitions WHERE id=? AND owner_user_id=?').bind(id,userId).first<Record<string,unknown>>();if(!row)throw new ApiError(404,'Informe no encontrado');return{id:String(row.id),name:String(row.name),purpose:String(row.purpose),definition:JSON.parse(String(row.definition_json))};}
export async function duplicateReportDefinition(db:D1Database,userId:number,role:Role,id:string,operationKey?:string){
 const payload={action:'duplicate',sourceReportId:id};
 const replay=await lookupExistingOperation(db,userId,operationKey,payload);
 if(replay)return{...(replay.result as Omit<ReportDefinitionWriteResult,'replayed'>),replayed:true};
 const old=await getReportDefinition(db,userId,id);const d=checkDefinition({...old.definition,name:`${old.name} (copia)`},role);
 if(d.name.length<1||d.name.length>120||d.purpose.length<1||d.purpose.length>500)throw new ApiError(400,'El informe requiere nombre y finalidad');
 return writeReportDefinition(db,userId,d,{operationKey,action:'duplicate',operationPayload:payload});
}
export async function reportDashboard(db:D1Database,from:unknown,to:unknown,scope:ReportScope){const {start,end}=dateBounds(from,to);const barns=await scopeBarns(db,scope);const where:string[]=['a.is_active=1'];const args:unknown[]=[];scopedClause(barns,'a.barn_id',where,args);const animals=await db.prepare(`SELECT COUNT(*) total,animal_type type FROM animals a WHERE ${where.join(' AND ')} GROUP BY animal_type`).bind(...args).all<Record<string,unknown>>();const barnCount=barns===null?await db.prepare('SELECT COUNT(*) total FROM barns WHERE status<>\'inactivo\'').first<Record<string,unknown>>():barns.length;const vaccineWhere:string[]=["v.status='pending'",'v.scheduled_date<=?'];const vaccineArgs:unknown[]=[currentFarmDate()];scopedClause(barns,'a.barn_id',vaccineWhere,vaccineArgs);const vaccines=await db.prepare(`SELECT COUNT(*) total FROM vaccine_occurrences v JOIN animals a ON a.id=v.animal_id WHERE ${vaccineWhere.join(' AND ')}`).bind(...vaccineArgs).first<Record<string,unknown>>();const dueWhere:string[]=["c.cycle_status='open'",'c.probable_farrowing_date BETWEEN ? AND ?'];const dueArgs:unknown[]=[currentFarmDate(),new Date(Date.parse(currentFarmDate()+'T12:00:00Z')+7*86400000).toISOString().slice(0,10)];scopedClause(barns,'c.barn_id',dueWhere,dueArgs);const farrow=await db.prepare(`SELECT COUNT(*) total FROM reproduction_cycles c WHERE ${dueWhere.join(' AND ')}`).bind(...dueArgs).first<Record<string,unknown>>();const salesWhere:string[]=["f.direction='income'","f.source_type='animal_sale'",'f.reversed_at IS NULL'];const salesArgs:unknown[]=[];if(start){salesWhere.push('f.operation_date>=?');salesArgs.push(start);}if(end){salesWhere.push('f.operation_date<=?');salesArgs.push(end);}scopedClause(barns,'fa.barn_id',salesWhere,salesArgs);const sales=await db.prepare(`SELECT f.currency_code currency,substr(f.operation_date,1,7) month,SUM(fa.amount_minor) amountMinor FROM financial_entries f JOIN financial_allocations fa ON fa.entry_id=f.id WHERE ${salesWhere.join(' AND ')} GROUP BY f.currency_code,substr(f.operation_date,1,7) ORDER BY month`).bind(...salesArgs).all<Record<string,unknown>>();const feedWhere:[string,...string[]]=["movement_type='delivery'"];const feedArgs:unknown[]=[];if(start){feedWhere.push('effective_date>=?');feedArgs.push(start);}if(end){feedWhere.push('effective_date<=?');feedArgs.push(end);}scopedClause(barns,'destination_barn_id',feedWhere,feedArgs);const feed=await db.prepare(`SELECT substr(effective_date,1,7) month,COUNT(*) n,SUM(total_cost_minor) costMinor,currency_code currency FROM feed_movements WHERE ${feedWhere.join(' AND ')} GROUP BY currency_code,substr(effective_date,1,7) ORDER BY month`).bind(...feedArgs).all<Record<string,unknown>>();return{period:{from:start,to:end},asOf:currentFarmDate(),barnsIncluded:barns===null?'Todos los galpones activos':barns.length,totalAnimals:(animals.results??[]).reduce((n,r)=>n+Number(r.total),0),animalsByType:animals.results??[],barnCount:Number(typeof barnCount==='number'?barnCount:barnCount?.total??0),pendingVaccines:Number(vaccines?.total??0),upcomingFarrowings:Number(farrow?.total??0),sales:(sales.results??[]).map(r=>({...r,amountMinor:Number(r.amountMinor)})),feedCosts:(feed.results??[]).map(r=>({...r,costMinor:Number(r.costMinor??0),count:Number(r.n)})),currency:'PEN'};}
